import{_ as n,a0 as o,w as p,s as r,I as t,x as e,a1 as l,A as s,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"用 Pi-hole 和 Orange Pi 阻止家中所有设备上的广告 | LCTT x X-CMD","titleTemplate":false,"description":"用 Pi-hole 和 Orange Pi 阻止家中所有设备上的广告 | LCTT (201702) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 Pi-hole 和 Orange Pi 阻止家中所有设备上的广告 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 Pi-hole 和 Orange Pi 阻止家中所有设备上的广告 | LCTT (201702) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201702/20170107 Block Ads on All Your Devices at Home with Pi-hole and an Orange Pi","title":"用 Pi-hole 和 Orange Pi 阻止家中所有设备上的广告","tag":"201702","desc":""},"relativePath":"201702/20170107 Block Ads on All Your Devices at Home with Pi-hole and an Orange Pi.md","filePath":"[post].md"}'),h={name:"201702/20170107 Block Ads on All Your Devices at Home with Pi-hole and an Orange Pi.md"};function g(u,i,P,m,k,b){const a=o("Link");return p(),r("div",null,[i[23]||(i[23]=t("h1",{id:"用-pi-hole-和-orange-pi-阻止家中所有设备上的广告",tabindex:"-1"},[e("用 Pi-hole 和 Orange Pi 阻止家中所有设备上的广告 "),t("a",{class:"header-anchor",href:"#用-pi-hole-和-orange-pi-阻止家中所有设备上的广告","aria-label":"Permalink to “用 Pi-hole 和 Orange Pi 阻止家中所有设备上的广告”"},"​")],-1)),t("p",null,[i[1]||(i[1]=e("你是否很恼火地发现你的浏览器、智能手机和平板上不装广告拦截器不行？ 至少我是这样的。我家里有一些“智能”设备，但是它们似乎没有任何类型的广告拦截软件。 好了，我了解到 ",-1)),l(a,{href:"https://pi-hole.net/"},{default:s(()=>[...i[0]||(i[0]=[e("Pi-hole",-1)])]),_:1}),i[2]||(i[2]=e(" 是一个可以运行在树莓派板子上的广告拦截软件，它能在各种广告到达你的设备之前拦截它们。它允许你将任何域加入到黑名单或白名单，并且它有一个很好的仪表盘面板，可以让你深入了解你的家庭网络最常访问的域/网站、最活跃的设备和最常见的广告商。",-1))]),i[24]||(i[24]=d(`<p>Pi-hole 原本是运行在树莓派上的，但我想知道它能否在我运行 Armbian Linux 的廉价 Orange Pi 上运行。 好吧，它绝对可以！下面是我让 Pi-hole 能快速运行的方法。</p><h3 id="安装-pi-hole" tabindex="-1">安装 Pi-hole <a class="header-anchor" href="#安装-pi-hole" aria-label="Permalink to “安装 Pi-hole”">​</a></h3><p>安装 Pi-hole 是使用终端完成的，所以打开你的 Orange Pi 桌面上的终端或使用 ssh 连接。</p><p>因为需要下载软件，所以进入到一个你选定的目录，确保你有写入权限。像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd &lt;your preferred directory&gt;/</span></span></code></pre></div><p>我没有选择 Pi-hole 主页上的“单条命令”安装方式。 我的意思是，他们在那条命令下面写着“用管道到 bash 可能是危险的”，本地安装“更安全”。所以，这里是我的本地安装步骤：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git clone --depth 1 https://github.com/pi-hole/pi-hole.git Pi-hole</span></span>
<span class="line"><span>cd Pi-hole/automated\\ install/</span></span>
<span class="line"><span>./basic-install.sh</span></span></code></pre></div><p>如果你没有以 root 用户身份登录，那么这个安装脚本将提示你输入密码，然后再继续。 如果需要，脚本将下载并安装一些必备的 Linux 软件包。接着它会显示一个红蓝界面，提示你回答有关如何配置 Pi-hole 的几个问题。以我的经验，直接接受默认值就可以了，我后来发现 Pi-hole 的 web 应用可以让你更改设置，比如 DNS 提供商。</p><p>该脚本将告诉你在图形界面和终端中 Pi-hole 的密码。 请记住该密码！</p><p>脚本还会告诉你 Pi-hole 的网址，应该像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>http://&lt;your pi’s IP address&gt;/admin</span></span></code></pre></div><p>或者类似这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>http://orangepipc/admin</span></span></code></pre></div><p>输入 Pi-hole 密码，接着你会看到像下面这样的漂亮的仪表盘面板：</p><p><img src="https://i1.wp.com/piboards.com/wp-content/uploads/2017/01/ph-hole.png?resize=640%2C532" alt="Ph-hole"></p><p>请记住更改家庭网络路由器上的 DNS 设置并使用你的 Orange Pi 的地址。 否则，广告不会被过滤！</p><p>上面的说明与 Pi-hole 网站提供的替代“安全”方法大致相同，尽管 Armbian 没有被列为官方支持的操作系统。我相信这些说明应该在树莓派或其他运行某种形式的基于 Debian 的 Linux 操作系统的 Pi 上工作。但是，我并没有测试这一点，所以期待听到你的经验（请给我留下简短的评论）。</p><h3 id="思考和观察" tabindex="-1">思考和观察 <a class="header-anchor" href="#思考和观察" aria-label="Permalink to “思考和观察”">​</a></h3><p>运行 Pi-hole 一段时间，并研究了在 Pi-hole 面板上出现的信息后，我发现有很多我不知道的网络活动在进行，而它们并不都是我批准的活动。例如，有一些我不知道的关于游戏程序的“有趣”连接从我的孩子的设备上发出，还有社交网络程序显然一直在给我发送骚扰数据。总之，无论是否是无害流量，我很高兴减少了流量负载，即使仅减少了一点点……我的意思是，为什么我应该允许我不想要的或者不关心的应用程序和广告吃掉我的网络流量？好吧，现在他们被封锁了。</p>`,19)),t("p",null,[i[4]||(i[4]=e("像这样为 Orange Pi 设置广告屏蔽很便宜、容易，限制一些不必要的流量在我的家庭网络中进出（特别是与孩子们相关的）使我感到放松多了。如果有兴趣，你可以看看我的上一篇文章，如何",-1)),l(a,{href:"http://piboards.com/2017/01/04/easy-set-up-orange-pi/"},{default:s(()=>[...i[3]||(i[3]=[e("轻松设置一个 Orange Pi",-1)])]),_:1}),i[5]||(i[5]=e("，并使用下面的链接来查看 Orange Pi 是多么便宜。我相信这是一个值得的投资。",-1))]),t("ul",null,[t("li",null,[i[7]||(i[7]=e("Amazon 上的 Orange Pi （受益链接）：  ",-1)),l(a,{href:"https://www.amazon.com/gp/product/B018W6OTIM/ref=as_li_tl?ie=UTF8&camp=1789&creative=9325&creativeASIN=B018W6OTIM&linkCode=as2&tag=piboards-20&linkId=ac292a536d58eabf1ee73e2c575e1111"},{default:s(()=>[...i[6]||(i[6]=[e("Orange Pi PC Single Board Computer Quad Core ARM Cortex-A7 1GB DDR3 4K Decode",-1)])]),_:1})]),t("li",null,[l(a,{href:"http://s.click.aliexpress.com/e/bAMVj2R"},{default:s(()=>[...i[8]||(i[8]=[e("AliExpress 上的 Orange Pi 商店",-1)])]),_:1}),i[9]||(i[9]=e(" （受益链接）",-1))])]),i[25]||(i[25]=t("p",null,"更新：具有讽刺意味的是，如果你成功地按照这篇文章设置了 Pi-hole，这个站点上（s.click.aliexpress.com）的受益链接会被屏蔽，是否将它加入到白名单取决于你。",-1)),i[26]||(i[26]=t("hr",null,null,-1)),t("p",null,[i[11]||(i[11]=e("via: ",-1)),l(a,{href:"http://piboards.com/2017/01/07/block-ads-on-all-your-devices-at-home-with-pi-hole-and-an-orange-pi/"},{default:s(()=>[...i[10]||(i[10]=[e("http://piboards.com/2017/01/07/block-ads-on-all-your-devices-at-home-with-pi-hole-and-an-orange-pi/",-1)])]),_:1})]),t("p",null,[i[15]||(i[15]=e("作者：",-1)),l(a,{href:"http://piboards.com/author/piguy/"},{default:s(()=>[...i[12]||(i[12]=[e("MIKE WILMOTH",-1)])]),_:1}),i[16]||(i[16]=e(" 译者：",-1)),l(a,{href:"https://github.com/geekpi"},{default:s(()=>[...i[13]||(i[13]=[e("geekpi",-1)])]),_:1}),i[17]||(i[17]=e(" 校对：",-1)),l(a,{href:"https://github.com/jasminepeng"},{default:s(()=>[...i[14]||(i[14]=[e("jasminepeng",-1)])]),_:1})]),t("p",null,[i[20]||(i[20]=e("本文由 ",-1)),l(a,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...i[18]||(i[18]=[e("LCTT",-1)])]),_:1}),i[21]||(i[21]=e(" 原创编译，",-1)),l(a,{href:"https://linux.cn/"},{default:s(()=>[...i[19]||(i[19]=[e("Linux中国",-1)])]),_:1}),i[22]||(i[22]=e(" 荣誉推出",-1))])])}const x=n(h,[["render",g]]);export{T as __pageData,x as default};
